async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8", { fatal: true });

  let accepted = 0;
  let rejected = 0;
  let line = 1;
  let lineText = "";
  let lineHasBytes = false;
  let cancelRequired = true;

  async function visitLine(text, lineNumber) {
    if (/^[\u0009\u000D\u0020]*$/.test(text)) {
      return false;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected++;
      return false;
    }

    const result = await visitor({ line: lineNumber, value });
    accepted++;
    return result === false;
  }

  try {
    for (;;) {
      const { done, value } = await reader.read();

      if (done) {
        lineText += decoder.decode();

        if (lineHasBytes) {
          if (await visitLine(lineText, line)) {
            return { accepted, rejected, stopped: true };
          }
        }

        cancelRequired = false;
        return { accepted, rejected, stopped: false };
      }

      let start = 0;

      for (let index = 0; index < value.length; index++) {
        if (value[index] !== 0x0a) {
          continue;
        }

        if (index > start) {
          lineText += decoder.decode(value.subarray(start, index), {
            stream: true
          });
          lineHasBytes = true;
        }

        lineText += decoder.decode();

        if (await visitLine(lineText, line)) {
          return { accepted, rejected, stopped: true };
        }

        line++;
        lineText = "";
        lineHasBytes = false;
        start = index + 1;
      }

      if (start < value.length) {
        lineText += decoder.decode(value.subarray(start), { stream: true });
        lineHasBytes = true;
      }
    }
  } finally {
    if (cancelRequired) {
      await reader.cancel();
    }
    reader.releaseLock();
  }
}
